#!/usr/bin/env node
/**
 * `npm run db:bundle` — build a single SQL script from the migration history.
 *
 * The authoritative history stays `supabase/migrations/` (one file per change,
 * applied by the Supabase CLI). This script only *derives* a concatenated copy
 * for one situation: a brand-new project where the operator wants to set up the
 * schema with nothing but the Supabase SQL editor (no CLI, no database password,
 * no local tooling).
 *
 * The bundle is generated, never edited by hand, and is git-ignored so it can
 * never drift from the real history.
 *
 * Usage:
 *   npm run db:bundle            # writes supabase/bundle/campus-plus-schema.sql
 */

import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const migrationsDir = path.join(root, 'supabase', 'migrations');
const outDir = path.join(root, 'supabase', 'bundle');
const outFile = path.join(outDir, 'campus-plus-schema.sql');

const files = (await readdir(migrationsDir)).filter((name) => name.endsWith('.sql')).sort();
if (files.length === 0) {
  console.error('No migrations found in supabase/migrations.');
  process.exit(1);
}

const parts = [];
const checksums = [];

for (const [index, file] of files.entries()) {
  const sql = await readFile(path.join(migrationsDir, file), 'utf8');
  parts.push(
    `\n-- ${'='.repeat(74)}\n` +
      `-- FILE ${String(index + 1).padStart(2, '0')}/${files.length}  ${file}\n` +
      `-- ${'='.repeat(74)}\n\n${sql.trimEnd()}\n`,
  );
  checksums.push(`${String(index + 1).padStart(2, '0')}  ${file}  (${sql.split('\n').length} lines)`);
}

const header = `-- Campus+ — complete schema, permissions, functions and reference data.
--
-- GENERATED by \`npm run db:bundle\` from supabase/migrations/. Do not edit.
--
-- When to use this file
--   A brand-new Supabase project where you want the schema without the CLI:
--   open Supabase → SQL Editor → New query, paste this whole file, and Run.
--   It is a single one-shot script; run it once on an empty project.
--
-- Prefer the CLI when you can (it tracks applied migrations):
--   supabase link --project-ref <ref> && supabase db push
--
-- What it creates
--   extensions and enum tables → identity, roles and permissions → blocks →
--   communities → social → moderation → messaging → marketplace → campus →
--   Random → platform → auth hooks → reference data (college, roles,
--   permissions, categories, feature flags, platform settings) → realtime
--   policies and grants → column privileges → staff actions → hardening →
--   function grants → staff visibility.
--
-- After it succeeds
--   1. npm run verify:security     (proves anonymous access is denied)
--   2. sign in once, then grant the first Super Admin:
--      npm run role:grant -- --email you@pccoepune.org --role super_admin
--
-- Contents (${files.length} files):
${checksums.map((line) => `--   ${line}`).join('\n')}
`;

await mkdir(outDir, { recursive: true });
await writeFile(outFile, `${header}${parts.join('')}`, 'utf8');

const bytes = Buffer.byteLength(header + parts.join(''), 'utf8');
console.log(`Wrote ${path.relative(root, outFile)} — ${files.length} migrations, ${(bytes / 1024).toFixed(1)} KB.`);
console.log('Paste it into the Supabase SQL editor (a new query) and press Run.');
